input.content:
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #f4f5f7;
  color: #1c2126;
}
.app { min-height: 100vh; }
.topbar {
  background: #172b4d;
  color: white;
  padding: 14px 24px;
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.brand { color: white; font-weight: 700; font-size: 18px; text-decoration: none; }
.tag { color: #9fb3d1; font-size: 13px; }
.content { max-width: 900px; margin: 0 auto; padding: 24px; }
h1 { margin-top: 0; }
.muted { color: #6b778c; font-size: 13px; }
.empty { color: #6b778c; font-style: italic; }
.notice { background: #fff7e6; border: 1px solid #ffd591; padding: 10px 14px; border-radius: 6px; font-size: 14px; }

.inline-form { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.inline-form input, .inline-form select { padding: 8px 10px; border: 1px solid #dfe1e6; border-radius: 4px; flex: 1; min-width: 140px; }
.inline-form button { padding: 8px 16px; }

button {
  background: #0052cc;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 8px 14px;
  cursor: pointer;
  font-size: 14px;
}
button.secondary { background: #dfe1e6; color: #172b4d; }
button.danger { background: #de350b; }
button:disabled { opacity: 0.5; cursor: not-allowed; }

.card-list { list-style: none; padding: 0; }
.card {
  background: white;
  border: 1px solid #e2e4e9;
  border-radius: 6px;
  padding: 14px 16px;
  margin-bottom: 10px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.card-title { font-weight: 600; font-size: 16px; text-decoration: none; color: #0052cc; }

.suite-block { background: white; border: 1px solid #e2e4e9; border-radius: 6px; padding: 14px 16px; margin-bottom: 14px; }
.case-list { list-style: none; padding: 0; }
.case-list li { padding: 4px 0; }
.case-list label { display: flex; align-items: center; gap: 8px; }

.case-form { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
.case-form input, .case-form textarea, .case-form select { padding: 8px 10px; border: 1px solid #dfe1e6; border-radius: 4px; }
.case-form .row { display: flex; gap: 8px; }

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 12px;
  text-transform: capitalize;
  background: #dfe1e6;
  margin-left: 6px;
}
.badge.priority-low { background: #e3fcef; color: #006644; }
.badge.priority-medium { background: #fffae6; color: #974f00; }
.badge.priority-high { background: #ffebe6; color: #bf2600; }
.badge.priority-critical { background: #de350b; color: white; }

.badge.status-passed { background: #e3fcef; color: #006644; }
.badge.status-failed { background: #ffebe6; color: #bf2600; }
.badge.status-blocked { background: #eae6ff; color: #403294; }
.badge.status-retest { background: #fffae6; color: #974f00; }
.badge.status-untested { background: #dfe1e6; color: #42526e; }

.summary-bar { display: flex; gap: 8px; margin: 10px 0 16px; flex-wrap: wrap; }

.run-case-list { list-style: none; padding: 0; }
.run-case { background: white; border: 1px solid #e2e4e9; border-radius: 6px; padding: 12px 16px; margin-bottom: 10px; }
.run-case-header { display: flex; align-items: center; gap: 8px; cursor: pointer; }

.result-form { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; align-items: center; }
.result-form input, .result-form select { padding: 6px 8px; border: 1px solid #dfe1e6; border-radius: 4px; }
.jira-check { display: flex; align-items: center; gap: 4px; font-size: 13px; }

.history { margin-top: 10px; padding-top: 10px; border-top: 1px dashed #dfe1e6; font-size: 13px; }
.history ul { list-style: none; padding: 0; }
.history li { padding: 4px 0; }

section { margin-bottom: 28px; }

