.case-form input, .case-form textarea, .case-form select { padding: 8px 10px; border: 1px solid #dfe1e6; border-radius: 4px; }
.case-form .row { display: flex; gap: 8px; }

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 12px;
  text-transform: capitalize;
  background: #dfe1e6;
  margin-left: 6px;
}
.badge.priority-low { background: #e3fcef; color: #006644; }
.badge.priority-medium { background: #fffae6; color: #974f00; }
.badge.priority-high { background: #ffebe6; color: #bf2600; }
.badge.priority-critical { background: #de350b; color: white; }

.badge.status-passed { background: #e3fcef; color: #006644; }
.badge.status-failed { background: #ffebe6; color: #bf2600; }
.badge.status-blocked { background: #eae6ff; color: #403294; }
.badge.status-retest { background: #fffae6; color: #974f00; }
.badge.status-untested { background: #dfe1e6; color: #42526e; }

.summary-bar { display: flex; gap: 8px; margin: 10px 0 16px; flex-wrap: wrap; }

.run-case-list { list-style: none; padding: 0; }
.run-case { background: white; border: 1px solid #e2e4e9; border-radius: 6px; padding: 12px 16px; margin-bottom: 10px; }
.run-case-header { display: flex; align-items: center; gap: 8px; cursor: pointer; }

.result-form { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; align-items: center; }
.result-form input, .result-form select { padding: 6px 8px; border: 1px solid #dfe1e6; border-radius: 4px; }
.jira-check { display: flex; align-items: center; gap: 4px; font-size: 13px; }

.history { margin-top: 10px; padding-top: 10px; border-top: 1px dashed #dfe1e6; font-size: 13px; }
.history ul { list-style: none; padding: 0; }
.history li { padding: 4px 0; }

section { margin-bottom: 28px; }

